// FUNÇÃO HELPER --> CRIA MATERIAL COM COMPOSIÇÃO FIXA

G4Material* DetectorConstruction::CreateAtmosMaterial(
    G4String name,
    G4double density,
    G4double temperature,
    G4double pressure)
{
    // Elementos (static = só cria uma vez!)
    static G4NistManager* nist = G4NistManager::Instance();
    static G4Element* elC  = nist->FindOrBuildElement("C");
    static G4Element* elO  = nist->FindOrBuildElement("O");
    static G4Element* elN  = nist->FindOrBuildElement("N");
    ///static G4Element* elAr = nist->FindOrBuildElement("Ar");

    static G4Element* elAr40 = nullptr;
    if (!elAr40) {
        G4Isotope* Ar40_isotope = new G4Isotope("Ar40", 18, 40, 39.948*g/mole);
        elAr40 = new G4Element("Argon40", "Ar40", 1);
        elAr40->AddIsotope(Ar40_isotope, 100*perCent);
    }

    // Cria material
    G4Material* mat = new G4Material(name,
                                     density,
                                     4,
                                     kStateGas,
                                     temperature,
                                     pressure);

    // COMPOSIÇÃO ATMOSFERA MARTE (nova!)
    // CO2: 96%    → C: 27.27%, O: 72.73% (de CO2)
    // O2:  0.145% → O: 0.145%
    // N2:  1.89%  → N: 1.89%
    // Ar:  1.9%   → Ar: 1.9%
    // CO:  0.065% → C: 0.028%, O: 0.037% (de CO)

    // Cálculo total:
    // C total  = 27.27% (de CO2) + 0.028% (de CO) = 27.298%
    // O total  = 72.73% (de CO2) + 0.145% (de O2) + 0.037% (de CO) = 72.912%
    // N total  = 1.89%
    // Ar total = 1.9%
    // SOMA = 100%

    // Converter para frações de massa:
    // Peso molecular: C=12, O=16, N=14, Ar=40

    // Fração de massa simplificada (já calculada):
    mat->AddElement(elC,  0.138);   // ~27.3% molar → 13.8% massa
    mat->AddElement(elO,  0.738);   // ~72.9% molar → 73.8% massa
    mat->AddElement(elN,  0.053);   // ~1.89% molar → 5.3% massa
    mat->AddElement(elAr40, 0.071);   // ~1.9% molar  → 7.1% massa

    return mat;
}

